import {
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs'
import { join, relative, sep } from 'node:path'

const GENERATED_NOTICE = `/**
 * These files were auto-generated by openapi-typescript.
 * Do not make direct changes to them.
 */`

export function writeModularOpenApiTypes(rawPath, outputRoot) {
  const source = readFileSync(rawPath, 'utf8').replaceAll('\r\n', '\n')
  const paths = extractInterface(source, 'paths')
  const components = extractInterface(source, 'components')
  const operations = extractInterface(source, 'operations')
  const schemas = extractObjectMember(components.body, 'schemas')
  const aliases = source.slice(components.end, operations.start).trim()
  const webhooks = source.match(/^export type webhooks = .*;$/m)?.[0]
  if (!webhooks || !aliases.startsWith('export type ')) {
    throw new Error('Unable to identify generated OpenAPI root type aliases.')
  }

  const moduleRoot = join(outputRoot, 'openapi')
  rmSync(moduleRoot, { recursive: true, force: true })
  rmSync(join(outputRoot, 'openapi.ts'), { force: true })
  mkdirSync(moduleRoot, { recursive: true })

  const pathParts = writeParts({
    body: paths.body,
    directory: join(moduleRoot, 'paths'),
    interfacePrefix: 'PathsPart',
    importLine: "import type { operations } from '../operations'",
  })
  const schemaParts = writeParts({
    body: schemas.body,
    directory: join(moduleRoot, 'schemas'),
    interfacePrefix: 'SchemasPart',
    importLine: "import type { components } from '../components'",
  })
  const operationParts = writeParts({
    body: operations.body,
    directory: join(moduleRoot, 'operations'),
    interfacePrefix: 'OperationsPart',
    importLine: "import type { components } from '../components'",
  })

  writeMasterInterface(join(moduleRoot, 'paths.ts'), 'paths', pathParts, './paths')
  writeComponents(
    join(moduleRoot, 'components.ts'),
    schemaParts,
    components.body.slice(schemas.end),
  )
  writeMasterInterface(
    join(moduleRoot, 'operations.ts'),
    'operations',
    operationParts,
    './operations',
  )
  writeGenerated(join(moduleRoot, 'types.ts'), [
    "import type { components } from './components'",
    '',
    aliases,
  ].join('\n'))
  writeGenerated(join(outputRoot, 'openapi.ts'), [
    "export type { paths } from './openapi/paths'",
    "export type { components } from './openapi/components'",
    "export type { operations } from './openapi/operations'",
    "export type * from './openapi/types'",
    '',
    webhooks,
  ].join('\n'))
}

export function compareGeneratedTree(expectedRoot, actualRoot) {
  const expectedFiles = walkFiles(expectedRoot)
  const actualFiles = walkFiles(actualRoot)
  const expectedRelative = expectedFiles.map((path) => normalize(relative(expectedRoot, path)))
  const actualRelative = actualFiles.map((path) => normalize(relative(actualRoot, path)))
  if (expectedRelative.join('\n') !== actualRelative.join('\n')) {
    throw new Error([
      'Generated TypeScript contract file inventory drift detected.',
      `Expected: ${expectedRelative.join(', ')}`,
      `Actual: ${actualRelative.join(', ')}`,
    ].join('\n'))
  }
  for (let index = 0; index < expectedFiles.length; index += 1) {
    const expected = readFileSync(expectedFiles[index], 'utf8').replaceAll('\r\n', '\n')
    const actual = readFileSync(actualFiles[index], 'utf8').replaceAll('\r\n', '\n')
    if (expected !== actual) {
      throw new Error(`Generated TypeScript contract drift detected in ${expectedRelative[index]}.`)
    }
  }
}

function writeParts({ body, directory, interfacePrefix, importLine }) {
  const members = topLevelMembers(body)
  const chunks = []
  let current = []
  for (const member of members) {
    const proposed = [...current, member]
    if (renderPart(interfacePrefix, chunks.length + 1, proposed, importLine).split('\n').length > 500) {
      if (!current.length) throw new Error(`${interfacePrefix} contains an item over 500 lines.`)
      chunks.push(current)
      current = [member]
    } else {
      current = proposed
    }
  }
  if (current.length) chunks.push(current)
  mkdirSync(directory, { recursive: true })
  return chunks.map((chunk, index) => {
    const ordinal = index + 1
    const name = `${interfacePrefix}${String(ordinal).padStart(2, '0')}`
    const filename = `part-${String(ordinal).padStart(2, '0')}.ts`
    writeFileSync(join(directory, filename), renderPart(interfacePrefix, ordinal, chunk, importLine))
    return { name, filename }
  })
}

function renderPart(interfacePrefix, ordinal, members, importLine) {
  const name = `${interfacePrefix}${String(ordinal).padStart(2, '0')}`
  return `${GENERATED_NOTICE}\n\n${importLine}\n\nexport interface ${name} {\n${members.join('\n')}\n}\n`
}

function writeMasterInterface(path, name, parts, directory) {
  const imports = parts.map((part) => (
    `import type { ${part.name} } from '${directory}/${part.filename.slice(0, -3)}'`
  ))
  const extensions = parts.map((part) => part.name).join(', ')
  writeGenerated(path, `${imports.join('\n')}\n\nexport interface ${name} extends ${extensions} {}`)
}

function writeComponents(path, parts, tail) {
  const imports = parts.map((part) => (
    `import type { ${part.name} } from './schemas/${part.filename.slice(0, -3)}'`
  ))
  const schemas = parts.map((part) => part.name).join(' & ')
  writeGenerated(path, [
    imports.join('\n'),
    '',
    'export interface components {',
    `    schemas: ${schemas};${tail}`,
    '}',
  ].join('\n'))
}

function writeGenerated(path, content) {
  const output = `${GENERATED_NOTICE}\n\n${content.trim()}\n`
  if (output.split('\n').length > 501) {
    throw new Error(`Generated file ${path} exceeds 500 lines.`)
  }
  mkdirSync(join(path, '..'), { recursive: true })
  writeFileSync(path, output)
}

function extractInterface(source, name) {
  const pattern = new RegExp(`export interface ${name}\\s*\\{`)
  const match = pattern.exec(source)
  if (!match) throw new Error(`Unable to find generated interface ${name}.`)
  const open = source.indexOf('{', match.index)
  const close = findMatchingBrace(source, open)
  if (close < 0) throw new Error(`Unable to parse generated interface ${name}.`)
  return {
    body: source.slice(open + 1, close),
    start: match.index,
    end: close + 1,
  }
}

function extractObjectMember(body, name) {
  const pattern = new RegExp(`(^|\\n)\\s*${name}:\\s*\\{`)
  const match = pattern.exec(body)
  if (!match) throw new Error(`Unable to find generated object member ${name}.`)
  const open = body.indexOf('{', match.index)
  const close = findMatchingBrace(body, open)
  if (close < 0 || body[close + 1] !== ';') {
    throw new Error(`Unable to parse generated object member ${name}.`)
  }
  return { body: body.slice(open + 1, close), end: close + 2 }
}

function topLevelMembers(body) {
  const members = []
  let start = 0
  let braces = 0
  let brackets = 0
  let parentheses = 0
  scanCode(body, (character) => {
    if (character === '{') braces += 1
    else if (character === '}') braces -= 1
    else if (character === '[') brackets += 1
    else if (character === ']') brackets -= 1
    else if (character === '(') parentheses += 1
    else if (character === ')') parentheses -= 1
    else if (character === ';' && braces === 0 && brackets === 0 && parentheses === 0) return true
    return false
  }, (index) => {
    const member = body.slice(start, index + 1).trim()
    if (member) members.push(member)
    start = index + 1
  })
  if (body.slice(start).trim()) throw new Error('Generated interface has an unterminated member.')
  return members
}

function findMatchingBrace(source, open) {
  let depth = 0
  let result = -1
  scanCode(source, (character, index) => {
    if (index < open) return false
    if (character === '{') depth += 1
    else if (character === '}') {
      depth -= 1
      if (depth === 0) {
        result = index
        return true
      }
    }
    return false
  }, () => {})
  return result
}

function scanCode(source, visit, boundary) {
  let state = 'code'
  for (let index = 0; index < source.length; index += 1) {
    const character = source[index]
    const next = source[index + 1]
    if (state === 'lineComment') {
      if (character === '\n') state = 'code'
      continue
    }
    if (state === 'blockComment') {
      if (character === '*' && next === '/') {
        state = 'code'
        index += 1
      }
      continue
    }
    if (state !== 'code') {
      if (character === '\\') index += 1
      else if (character === state) state = 'code'
      continue
    }
    if (character === '/' && next === '/') {
      state = 'lineComment'
      index += 1
    } else if (character === '/' && next === '*') {
      state = 'blockComment'
      index += 1
    } else if (character === '"' || character === "'" || character === '`') {
      state = character
    } else if (visit(character, index)) {
      boundary(index)
      if (source[index] === '}') return
    }
  }
}

function walkFiles(directory) {
  if (!statSync(directory).isDirectory()) return [directory]
  return readdirSync(directory).sort().flatMap((entry) => {
    const path = join(directory, entry)
    return statSync(path).isDirectory() ? walkFiles(path) : [path]
  })
}

function normalize(path) {
  return path.split(sep).join('/')
}
